      }
    }
  },
  "teacher_block": {
    "explanation": "Le problème de la saturation mémoire survient quand on utilise `pandas.read_csv()` ou `read_parquet()` sur un fichier plus gros que la RAM. La solution consiste à utiliser des moteurs de calcul qui travaillent par 'morceaux' (chunks) ou qui créent un graphe de calcul sans charger les données immédiatement.",
    "tutorial": [
      {
        "step": 1,
        "title": "Lancer l'environnement",
        "content": "Déployez le service Jupyter configuré. Le script d'init installera automatiquement les librairies nécessaires."
      },
      {
        "step": 2,
        "title": "Utiliser le Chunking (Pandas)",
        "content": "Utilisez `pd.read_csv(path, chunksize=10000)` pour itérer sur le fichier morceau par morceau."
      },
      {
        "step": 3,
        "title": "Passer au Lazy Loading (Polars/Dask)",
        "content": "Utilisez `polars.scan_parquet(path)` pour définir vos opérations, puis `.collect()` pour exécuter le calcul de manière optimisée."
      }
    ],
    "hello_world_script": {
      "language": "python",
      "filename": "s3_streaming_demo.py",
      "content": "import polars as pl\n\n# Exemple de lecture 'lazy' (ne charge pas en mémoire immédiatement)\n# Idéal pour les gros fichiers sur S3\ndef process_large_file(s3_path):\n    q = (\n        pl.scan_parquet(s3_path)\n        .filter(pl.col('valeur') %C2%BB 100)\n        .group_by('categorie')\n        .agg(pl.col('valeur').mean())\n    )\n    return q.collect()\n\nprint('Configuration prête pour le streaming de données.')"
    },
    "best_practices": [
